/usr/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
import re
zones=['.','com','net','edu','it','example.com','company.com','service.com','lab.net','tools.net','university.edu','campus.edu','unibo.it','comune.it','regione.it','shop.example.com','blog.example.com','dept.company.com','intranet.company.com','api.service.com','research.lab.net','ai.research.lab.net','data.research.lab.net','dev.lab.net','ci.tools.net','vpn.university.edu','courses.university.edu','portal.campus.edu','studenti.unibo.it','servizi.comune.it','dati.regione.it']
ips={}
for i in range(1,41):
 s=Path(f'pc{i}.startup').read_text(); m=re.search(r\"inet (\\d+\\.\\d+\\.\\d+\\.\\d+)/24\",s); assert m; ips[i]=m.group(1)
assert len(set(ips.values()))==40
assert not any(Path(f'pc{i}/etc/bind').exists() for i in range(1,33))
parents={z:('.' if '.' not in z else z.split('.',1)[1]) for z in zones[1:]}
assert all(p in zones for p in parents.values())
ns={z:('a.root-servers.' if z=='.' else 'ns.'+z+'.') for z in zones}
for i,z in enumerate(zones,1):
 d=Path(f'pc{i}/etc/bind'); d.mkdir(parents=True)
 filename='db.root' if z=='.' else 'db.'+z
 (d/'named.conf').write_text('options { directory \"/var/cache/bind\"; recursion no; allow-query { any; }; dnssec-validation no; listen-on { any; }; listen-on-v6 { none; }; };\\n'+f'zone \"{z}\" {{ type master; file \"/etc/bind/{filename}\"; }};\\n')
 hostmaster='hostmaster.' if z=='.' else 'hostmaster.'+z+'.'
 lines=['"'$TTL 3600'"',f'@ IN SOA {ns[z]} {hostmaster} ( 1 3600 900 604800 300 )',f'@ IN NS {ns[z]}',f'{ns[z]} IN A {ips[i]}']
 if i>=16: lines.append(f'@ IN A {ips[i]}')
 if z=='example.com': lines.append(f'www IN A {ips[6]}')
 if z in ('company.com','university.edu'):
  lines.extend([f'@ IN MX 10 mail.{z}.',f'mail IN A {ips[i]}'])
 for child,parent in parents.items():
  if parent==z:
   j=zones.index(child)+1
   lines.extend([f'{child}. IN NS {ns[child]}',f'{ns[child]} IN A {ips[j]}'])
 (d/filename).write_text('\\n'.join(lines)+'\\n')
 with Path(f'pc{i}.startup').open('a') as f: f.write('\\n# DNS authoritative server\\nsystemctl restart named\\n')
d=Path('pc32/etc/bind'); d.mkdir(parents=True)
(d/'named.conf').write_text('options { directory \"/var/cache/bind\"; recursion yes; allow-recursion { any; }; allow-query { any; }; dnssec-validation no; listen-on { any; }; listen-on-v6 { none; }; };\\nzone \".\" { type hint; file \"/etc/bind/db.hints\"; };\\n')
(d/'db.hints').write_text(f'. 3600000 IN NS a.root-servers.\\na.root-servers. 3600000 IN A {ips[1]}\\n')
with Path('pc32.startup').open('a') as f: f.write('\\n# DNS recursive resolver\\nsystemctl restart named\\n')
for i in range(33,41):
 with Path(f'pc{i}.startup').open('a') as f: f.write(f'\\n# Local DNS resolver\\necho \"nameserver {ips[32]}\" > /etc/resolv.conf\\n')
print('Generated 31 zones, 30 delegations; resolver',ips[32],'; root',ips[1],'; www',ips[6])
PY"

